  "Sem {0} (filtro da barra lateral)": "Đang ẩn {0} (bộ lọc ở thanh bên)",
  "Recolher feed ( ] )": "Thu gọn bảng tin ( ] )",
  "Abrir feed ( ] )": "Mở bảng tin ( ] )",

  // client/src/ui/format.ts
  "agora": "vừa xong",
