  "  Sobrou do CodeTown; depois de conferir o escritório, apague com: {0}": "  Còn sót lại từ CodeTown; sau khi kiểm tra văn phòng, hãy xóa bằng: {0}",
  "  Logs: npm run docker:logs · Parar: npm run docker:down": "  Log: npm run docker:logs · Dừng: npm run docker:down",
