  // scripts/hooks-install.ts
  "Aguardando resposta no Habblaud": "Đang chờ câu trả lời trong Habblaud",
  "Uso: npm run hooks:<install|uninstall|status> [-- opções]\n\n  install     acrescenta o hook de permissão do Habblaud em cada conta (faz backup do settings.json)\n  uninstall   tira o hook do Habblaud de cada conta (os outros hooks ficam)\n  status      mostra se o hook está instalado e se o Habblaud está respondendo pedidos\n\nOpções:\n  --dry-run        mostra o que mudaria, sem gravar nada\n  --node <cmd>     comando do node usado no hook (padrão: detectado no PATH)\n  --port <n>       porta do Habblaud (padrão: HABBLAUD_PORT ou {0})\n  --timeout <s>    quanto o hook espera sua resposta no Habblaud antes de devolver o pedido ao terminal\n                   (padrão: {1} s)\n  -h, --help       mostra esta ajuda\n\nContas: as mesmas do servidor (~/.claude* com projects/ ou sessions/, CLAUDE_CONFIG_DIR ou\nHABBLAUD_CLAUDE_DIRS).": "Cách dùng: npm run hooks:<install|uninstall|status> [-- tùy chọn]\n\n  install     thêm hook xin quyền của Habblaud vào mỗi tài khoản (sao lưu settings.json)\n  uninstall   gỡ hook của Habblaud khỏi mỗi tài khoản (các hook khác giữ nguyên)\n  status      cho biết hook đã được cài chưa và Habblaud có đang xử lý yêu cầu không\n\nTùy chọn:\n  --dry-run        cho biết sẽ thay đổi gì, không ghi gì cả\n  --node <cmd>     lệnh node dùng trong hook (mặc định: tìm trong PATH)\n  --port <n>       cổng của Habblaud (mặc định: HABBLAUD_PORT hoặc {0})\n  --timeout <s>    hook chờ câu trả lời của bạn trong Habblaud bao lâu trước khi trả yêu cầu về terminal\n                   (mặc định: {1} giây)\n  -h, --help       hiện trợ giúp này\n\nTài khoản: giống của máy chủ (~/.claude* có projects/ hoặc sessions/, CLAUDE_CONFIG_DIR hoặc\nHABBLAUD_CLAUDE_DIRS).",
  "atualizado (novo caminho do Habblaud, do node ou das opções)": "đã cập nhật (đường dẫn Habblaud, đường dẫn node hoặc tùy chọn mới)",
  "instalado": "đã cài",
  "hook do Habblaud removido": "đã gỡ hook của Habblaud",
  "--node precisa de um caminho.": "--node cần một đường dẫn.",
  "Nenhuma conta do Claude Code encontrada (~/.claude* com projects/ ou sessions/). Use HABBLAUD_CLAUDE_DIRS se estiverem em outro lugar.": "Không tìm thấy tài khoản Claude Code nào (~/.claude* có projects/ hoặc sessions/). Hãy dùng HABBLAUD_CLAUDE_DIRS nếu chúng ở chỗ khác.",
  " (esse arquivo não existe mais: o hook falha e vale só o terminal)": " (tệp đó không còn tồn tại: hook bị lỗi và chỉ terminal có hiệu lực)",
  "! {0}: o hook aponta para {1}{2}; rode npm run hooks:install para atualizar": "! {0}: hook trỏ tới {1}{2}; hãy chạy npm run hooks:install để cập nhật",
  "• {0}: instalado ({1}; tempo limite {2} s)": "• {0}: đã cài ({1}; thời gian chờ {2} giây)",
  "Habblaud em http://127.0.0.1:{0}: fora do ar (com ele parado, o hook sai na hora e o terminal segue normal).": "Habblaud tại http://127.0.0.1:{0}: không chạy (khi nó dừng, hook thoát ngay và terminal hoạt động như bình thường).",
  "Habblaud em http://127.0.0.1:{0}: respondendo pedidos de permissão (com alguma página aberta).": "Habblaud tại http://127.0.0.1:{0}: đang xử lý yêu cầu xin quyền (khi có trang đang mở).",
  "Habblaud em http://127.0.0.1:{0}: no ar, mas responder pelo escritório está desligado (porta exposta na rede ou HABBLAUD_TERMINAL=0).": "Habblaud tại http://127.0.0.1:{0}: đang chạy, nhưng trả lời từ văn phòng đang tắt (cổng lộ ra mạng hoặc HABBLAUD_TERMINAL=0).",
  "Pronto. Com o Habblaud aberto no navegador, os pedidos de permissão aparecem no escritório e você": "Xong. Khi Habblaud mở trên trình duyệt, yêu cầu xin quyền sẽ hiện trong văn phòng và bạn",
  "pode aprovar ou recusar por lá; o diálogo continua no terminal e vale o que responder primeiro.": "có thể duyệt hoặc từ chối ở đó; hộp thoại vẫn ở trong terminal và câu trả lời nào đến trước sẽ được dùng.",
  "Sessões abertas costumam recarregar o settings.json sozinhas; se não, reabra a sessão.": "Các phiên đang mở thường tự tải lại settings.json; nếu không, hãy mở lại phiên.",
  "Para desfazer: npm run hooks:uninstall": "Để hoàn tác: npm run hooks:uninstall",
  "[hooks] Erro: {0}": "[hooks] Lỗi: {0}",
  "[hooks] Erro inesperado: {0}": "[hooks] Lỗi không mong muốn: {0}",

  // scripts/mod-install.ts
  "Uso: npm run mod:<install|uninstall|status> [-- opções]\n\n  install     instala o mod do Habblaud no Claude Code de cada conta (marketplace desta pasta + plugins)\n              e tira o que ele substitui: o tap de statusline e o hook de permissão antigos e o mod do\n              nome antigo (codetown)\n  uninstall   tira os plugins e o marketplace do Habblaud de cada conta (e os do nome antigo, se sobraram)\n  status      mostra, por conta, o marketplace, os plugins (e versões) e o que sobrou do jeito antigo\n\nOpções:\n  --sem-permissoes   não instala o plugin de responder permissões pelo escritório (e mantém o hook antigo)\n  --sem-mensagens    não instala o plugin de mandar mensagens pelo escritório (um já instalado continua)\n  --conta <pasta>    só esta conta (ex.: --conta ~/.claude-conta2); pode repetir\n  --dry-run          mostra o que faria, sem instalar nem gravar nada\n  --claude <cmd>     comando do Claude Code (padrão: claude, do PATH)\n  -h, --help         mostra esta ajuda\n\nPrecisa do Claude Code {0} ou mais novo. Em versões anteriores, use o jeito antigo:\nnpm run usage:install (uso ao vivo) e npm run hooks:install (responder permissões); mandar mensagens pelo\nescritório só existe com o mod.\n\nContas: as mesmas do servidor (~/.claude* com projects/ ou sessions/, CLAUDE_CONFIG_DIR ou\nHABBLAUD_CLAUDE_DIRS). Uso capturado em HABBLAUD_USAGE_DIR (padrão ~/.habblaud/usage).": "Cách dùng: npm run mod:<install|uninstall|status> [-- tùy chọn]\n\n  install     cài mod Habblaud vào Claude Code của mỗi tài khoản (marketplace + plugin của thư mục này)\n              và gỡ những gì nó thay thế: nhánh statusline cũ, hook xin quyền cũ và mod mang\n              tên cũ (codetown)\n  uninstall   gỡ các plugin và marketplace của Habblaud khỏi mỗi tài khoản (và các bản tên cũ, nếu còn)\n  status      cho biết, theo từng tài khoản, marketplace, các plugin (và phiên bản) và những gì còn lại của cách cũ\n\nTùy chọn:\n  --sem-permissoes   không cài plugin trả lời xin quyền từ văn phòng (và giữ hook cũ)\n  --sem-mensagens    không cài plugin gửi tin nhắn từ văn phòng (bản đã cài vẫn giữ)\n  --conta <folder>   chỉ tài khoản này (ví dụ --conta ~/.claude-conta2); có thể lặp lại\n  --dry-run          cho biết sẽ làm gì, không cài hay ghi gì cả\n  --claude <cmd>     lệnh Claude Code (mặc định: claude, từ PATH)\n  -h, --help         hiện trợ giúp này\n\nCần Claude Code {0} trở lên. Với các phiên bản cũ hơn, hãy dùng cách cũ:\nnpm run usage:install (mức dùng trực tiếp) và npm run hooks:install (trả lời xin quyền); gửi tin nhắn từ\nvăn phòng chỉ có với mod.\n\nTài khoản: giống của máy chủ (~/.claude* có projects/ hoặc sessions/, CLAUDE_CONFIG_DIR hoặc\nHABBLAUD_CLAUDE_DIRS). Mức dùng được ghi vào HABBLAUD_USAGE_DIR (mặc định ~/.habblaud/usage).",
