  "rode npm run mod:install para mandar mensagens pelo escritório (plugin {0})": "hãy chạy npm run mod:install để gửi tin nhắn từ văn phòng (plugin {0})",
  "ainda com o nome antigo ({0}); o docker:up não troca sozinho: rode npm run mod:install": "vẫn mang tên cũ ({0}); docker:up không tự đổi: hãy chạy npm run mod:install",
