  "carrega {0} de {1}": "tải {0} từ {1}",
  "esta pasta": "thư mục này",
  "! nome antigo ainda registrado: {0}; npm run mod:install troca pelo habblaud": "! tên cũ vẫn còn đăng ký: {0}; npm run mod:install sẽ thay bằng habblaud",
  "! tap de statusline antigo ainda instalado junto com o mod: npm run mod:install tira (ou npm run usage:uninstall)": "! nhánh statusline cũ vẫn được cài cùng mod: npm run mod:install sẽ gỡ nó (hoặc npm run usage:uninstall)",
  "tap de statusline antigo instalado (jeito antigo; o mod o substitui)": "đã cài nhánh statusline cũ (cách cũ; mod thay thế nó)",
  "! hook de permissão antigo ainda no settings.json junto com o plugin: os dois respondem; npm run mod:install tira (ou npm run hooks:uninstall)": "! hook xin quyền cũ vẫn có trong settings.json cùng plugin: cả hai đều trả lời; npm run mod:install sẽ gỡ nó (hoặc npm run hooks:uninstall)",
  "hook de permissão antigo instalado (jeito antigo; o plugin de permissões o substitui)": "đã cài hook xin quyền cũ (cách cũ; plugin quyền thay thế nó)",
  "! disableAllHooks está ligado no settings.json desta conta: nenhum mod (nem hook) roda": "! disableAllHooks đang bật trong settings.json của tài khoản này: không mod (hay hook) nào chạy",
  "--conta precisa da pasta da conta (ex.: --conta ~/.claude-conta2).": "--conta cần thư mục tài khoản (ví dụ --conta ~/.claude-conta2).",
