  "nenhum uso capturado ainda (chega depois da próxima resposta numa sessão aberta desta conta)": "chưa ghi được mức dùng nào (sẽ có sau câu trả lời tiếp theo trong một phiên đang mở của tài khoản này)",
  "Nenhuma conta do Claude Code encontrada (~/.claude* com projects/ ou sessions/). Use --conta <pasta> ou HABBLAUD_CLAUDE_DIRS.": "Không tìm thấy tài khoản Claude Code nào (~/.claude* có projects/ hoặc sessions/). Hãy dùng --conta <folder> hoặc HABBLAUD_CLAUDE_DIRS.",
  "Não achei {0}: esta pasta não tem o mod (versão antiga do Habblaud? rode git pull).": "không tìm thấy {0}: thư mục này không có mod (phiên bản Habblaud cũ? hãy chạy git pull).",
  "Não consegui rodar o Claude Code: {0}.": "Không thể chạy Claude Code: {0}.",
  "Instale o Claude Code (https://code.claude.com) ou diga onde ele está: npm run mod:<comando> -- --claude <caminho>": "Hãy cài Claude Code (https://code.claude.com) hoặc cho biết nó ở đâu: npm run mod:<command> -- --claude <path>",
  "! Não entendi a versão do Claude Code (\"{0}\"); sigo assim mesmo.": "! Không thể phân tích phiên bản Claude Code (\"{0}\"); vẫn tiếp tục.",
  "O mod precisa do Claude Code {0} ou mais novo, e este é o {1}.": "Mod cần Claude Code {0} trở lên, còn bản này là {1}.",
  "Atualize o Claude Code (claude update) e rode de novo. Ou use o jeito antigo, que funciona em versões anteriores:": "Hãy cập nhật Claude Code (claude update) rồi chạy lại. Hoặc dùng cách cũ, hoạt động được với các phiên bản cũ hơn:",
  "  npm run usage:install    # uso de 5h/semanal ao vivo (tap de statusline)": "  npm run usage:install    # mức dùng 5 giờ/tuần trực tiếp (nhánh statusline)",
  "  npm run hooks:install    # responder pedidos de permissão pelo escritório": "  npm run hooks:install    # trả lời yêu cầu xin quyền từ văn phòng",
