  "  ✗ não consegui gravar o settings.json ({0}); o tap e o hook antigos continuam": "  ✗ không thể ghi settings.json ({0}); nhánh và hook cũ vẫn còn",
  "Pronto. Sessões novas do Claude Code já carregam o mod; nas que já estão abertas, rode /reload-plugins (ou": "Xong. Các phiên Claude Code mới đã tải mod; với các phiên đang mở, hãy chạy /reload-plugins (hoặc",
  "reabra a sessão). O uso de 5h/semanal chega ao Habblaud depois da próxima resposta de cada sessão.": "mở lại phiên). Mức dùng 5 giờ/tuần tới Habblaud sau câu trả lời tiếp theo của mỗi phiên.",
  "Para conferir: npm run mod:status · Para desfazer: npm run mod:uninstall": "Để kiểm tra: npm run mod:status · Để hoàn tác: npm run mod:uninstall",
  "Pronto. Sessões já abertas continuam com o mod até /reload-plugins (ou até reabrir a sessão).": "Xong. Các phiên đang mở vẫn giữ mod tới khi chạy /reload-plugins (hoặc tới khi mở lại phiên).",
  "Para voltar ao jeito antigo (Claude Code anterior ao 2.1.287): npm run usage:install e npm run hooks:install": "Để quay về cách cũ (Claude Code trước 2.1.287): npm run usage:install và npm run hooks:install",
  "Habblaud em http://127.0.0.1:{0}": "Habblaud tại http://127.0.0.1:{0}",
  "{0}: fora do ar (o mod segue gravando o uso; os pedidos de permissão ficam só no terminal).": "{0}: không chạy (mod vẫn ghi mức dùng; yêu cầu xin quyền chỉ ở trong terminal).",
  "{0}: no ar e respondendo pedidos de permissão (com alguma página aberta).": "{0}: đang chạy và xử lý yêu cầu xin quyền (khi có trang đang mở).",
  "{0}: no ar, mas responder pelo escritório está desligado (porta exposta na rede ou HABBLAUD_TERMINAL=0).": "{0}: đang chạy, nhưng trả lời từ văn phòng đang tắt (cổng lộ ra mạng hoặc HABBLAUD_TERMINAL=0).",
  "Mensagens pelo escritório: ligadas (chegam às sessões abertas com o plugin {0}).": "Tin nhắn từ văn phòng: bật (tới được các phiên đang mở có plugin {0}).",
  "Mensagens pelo escritório: desligadas no Habblaud (porta exposta na rede, HABBLAUD_TERMINAL=0 ou HABBLAUD_MENSAGENS=0).": "Tin nhắn từ văn phòng: tắt trong Habblaud (cổng lộ ra mạng, HABBLAUD_TERMINAL=0 hoặc HABBLAUD_MENSAGENS=0).",
