  // scripts/statusline-install.ts
  "Uso: npm run usage:<install|uninstall|status> [-- opções]\n\n  install     envolve o statusline de cada conta com o tap do Habblaud (faz backup do settings.json)\n  uninstall   restaura o statusline original de cada conta\n  status      mostra se o tap está instalado e quando chegou o último uso de cada conta\n\nOpções:\n  --dry-run        mostra o que mudaria, sem gravar nada\n  --node <cmd>     comando do node usado no statusline (padrão: detectado no PATH)\n  -h, --help       mostra esta ajuda\n\nContas: as mesmas do servidor (~/.claude* com projects/ ou sessions/, CLAUDE_CONFIG_DIR ou\nHABBLAUD_CLAUDE_DIRS). Uso capturado em HABBLAUD_USAGE_DIR (padrão ~/.habblaud/usage).": "Cách dùng: npm run usage:<install|uninstall|status> [-- tùy chọn]\n\n  install     bọc statusline của mỗi tài khoản bằng nhánh của Habblaud (sao lưu settings.json)\n  uninstall   khôi phục statusline gốc của mỗi tài khoản\n  status      cho biết nhánh đã được cài chưa và lần cuối mức dùng của mỗi tài khoản tới là khi nào\n\nTùy chọn:\n  --dry-run        cho biết sẽ thay đổi gì, không ghi gì cả\n  --node <cmd>     lệnh node dùng trong statusline (mặc định: tìm trong PATH)\n  -h, --help       hiện trợ giúp này\n\nTài khoản: giống của máy chủ (~/.claude* có projects/ hoặc sessions/, CLAUDE_CONFIG_DIR hoặc\nHABBLAUD_CLAUDE_DIRS). Mức dùng được ghi vào HABBLAUD_USAGE_DIR (mặc định ~/.habblaud/usage).",
