  "Começa na hora uma sessão do Claude Code em segundo plano no computador, na pasta escolhida; as permissões chegam aqui. Pasta que o Claude Code ainda não conhece abre no app do Claude e espera o Enter lá. Anexos vão para ~/.habblaud/attachments e o pedido leva os caminhos.": "Khởi động ngay một phiên Claude Code chạy nền trên máy tính, trong thư mục đã chọn; yêu cầu xin quyền sẽ tới đây. Thư mục mà Claude Code chưa biết sẽ mở trong ứng dụng Claude và chờ bạn bấm Enter ở đó. Tệp đính kèm được lưu vào ~/.habblaud/attachments và yêu cầu sẽ kèm đường dẫn của chúng.",
