  "serviço habblaud-remote-mdns ligado (para seguir ligado sem login: loginctl enable-linger)": "đã bật dịch vụ habblaud-remote-mdns (để giữ nó chạy khi đã đăng xuất: loginctl enable-linger)",
  "{0}: sem serviço automático; deixe npm run remote:mdns rodando ou use o IP": "{0}: không có dịch vụ tự động; hãy để npm run remote:mdns chạy hoặc dùng IP",
