  "    iPhone:  Ajustes > Perfil Baixado > Instalar; depois Ajustes > Geral > Sobre > Ajustes de Confiança de Certificados": "    iPhone:  Cài đặt > Đã tải về hồ sơ > Cài đặt; rồi Cài đặt > Cài đặt chung > Giới thiệu > Cài đặt tin cậy chứng nhận",
  "    Android: Configurações > Segurança > Criptografia e credenciais > Instalar certificado > Certificado de CA": "    Android: Cài đặt > Bảo mật > Mã hóa và thông tin đăng nhập > Cài đặt chứng chỉ > Chứng chỉ CA",
