  "Seu escritório vira um prédio numa cidade em pixel art, aceso enquanto os seus agentes trabalham.": "Văn phòng của bạn trở thành một tòa nhà trong thành phố pixel art, sáng đèn khi các agent của bạn làm việc.",
  "Crie um personagem, ande pela cidade e visite os prédios de outras pessoas.": "Tạo nhân vật, dạo quanh thành phố và ghé thăm tòa nhà của người khác.",
  "Cumprimente quem passa e deixe likes nos prédios, sem chat e sem spam.": "Chào người qua đường và thích các tòa nhà, không có chat và không có spam.",
  "Nada do seu trabalho sai do computador: só o tema, quantos andares e se cada personagem está ocupado ou à toa.": "Không gì về công việc của bạn rời khỏi máy tính: chỉ có chủ đề, số tầng và mỗi nhân vật đang bận hay rảnh.",
  "Ver a lista": "Xem danh sách",
