  "Criar conta": "Tạo tài khoản",
  "Agora não": "Để sau",
  "Não mostrar de novo": "Đừng hiện lại",
  "Você está na lista de espera": "Bạn đang trong danh sách chờ",
  "O acesso é liberado aos poucos, em lotes. Avisamos por e-mail quando chegar a sua vez.": "Quyền truy cập được mở dần theo từng đợt. Chúng tôi sẽ gửi email khi tới lượt bạn.",
  "Enquanto isso, o Habblaud continua normal e nada do escritório é enviado.": "Trong lúc đó, Habblaud vẫn hoạt động như bình thường và không gửi gì từ văn phòng.",
  "Entendi": "Đã hiểu",
  "Chegou a sua vez: crie o seu personagem e entre na cidade.": "Tới lượt bạn rồi: hãy tạo nhân vật và vào thành phố.",

