  "Entrar no seu prédio pela cidade e ver o que quem visita vê (sem nada do escritório real)": "Vào tòa nhà của bạn qua thành phố và xem những gì khách thấy (không có gì từ văn phòng thật của bạn)",
  "Avisar quando alguém visitar": "Báo cho tôi khi có người ghé thăm",
  "Um aviso quando o primeiro visitante entra no seu prédio. Você vê só quantos estão lá dentro, nunca quem.": "Một thông báo khi vị khách đầu tiên vào tòa nhà của bạn. Bạn chỉ thấy có bao nhiêu người bên trong, không bao giờ biết là ai.",
  "Alguém entrou no seu prédio no Habblaud World.": "Có người đã vào tòa nhà của bạn trong Habblaud World.",
  "1 visitante agora": "1 khách lúc này",
  "{0} visitantes agora": "{0} khách lúc này",
  "Este prédio não está no mundo agora.": "Tòa nhà này hiện không có trong thế giới.",
  "O prédio saiu do mundo: você voltou para a rua.": "Tòa nhà đã rời thế giới: bạn đã trở lại đường phố.",
  "Chegue mais perto da porta para entrar.": "Hãy lại gần cửa hơn để vào.",
  "O prédio fechou a visitas: você voltou para a rua.": "Tòa nhà đã đóng cửa với khách: bạn đã trở lại đường phố.",
  "Este prédio está fechado a visitas.": "Tòa nhà này đóng cửa với khách.",
  "Você não pode mais ficar neste prédio: voltou para a rua.": "Bạn không thể ở lại tòa nhà này nữa: bạn đã trở lại đường phố.",
  "Você não pode entrar neste prédio.": "Bạn không thể vào tòa nhà này.",
  "O prédio está lotado (20 visitantes). Tente daqui a pouco.": "Tòa nhà đã đầy (20 khách). Hãy thử lại sau ít phút.",
  "Esperando o dono": "Đang chờ chủ nhân",
