  "Só o nome, o papel, a ferramenta e o status de cada agente: o resto do escritório não sai do computador do dono.": "Chỉ có tên, vai trò, công cụ và trạng thái của từng agent: phần còn lại của văn phòng không bao giờ rời khỏi máy của chủ nhân.",
  "Sair pelo elevador": "Rời đi bằng thang máy",
