  "modo discreto": "chế độ kín đáo",
  "Seu prédio, como os outros veem": "Tòa nhà của bạn, như người khác thấy",
  "Prédio de {0}": "Tòa nhà của {0}",
  "esperando o dono": "đang chờ chủ nhân",
  "de olho no terminal": "đang xem terminal",
  "Prédio apagado: o dono pausou ou não está com o Habblaud aberto. As salas ficam escuras e vazias.": "Đèn tắt: chủ nhân đã tạm dừng hoặc không mở Habblaud. Các phòng tối và trống.",
  "Modo discreto: o dono não mostra os agentes. As salas aparecem vazias, com a luz acesa.": "Chế độ kín đáo: chủ nhân không hiện các agent. Các phòng trông trống, đèn vẫn sáng.",
  "O mundo está em manutenção; tentamos de novo em instantes.": "Thế giới đang bảo trì; chúng tôi sẽ thử lại sau giây lát.",
  "Conta excluída": "Đã xóa tài khoản",
  "A conta do Habblaud World foi excluída: o prédio e o perfil saíram do mundo e nada mais sai deste computador.": "Tài khoản Habblaud World đã bị xóa: tòa nhà và hồ sơ đã rời thế giới, và không gì khác rời khỏi máy này.",
  "Habblaud World: desligado (HABBLAUD_WORLD={0}).": "Habblaud World: tắt (HABBLAUD_WORLD={0}).",
  "Habblaud World: ligado: {0}": "Habblaud World: bật: {0}",
  "Habblaud World: ligado: {0} (padrão)": "Habblaud World: bật: {0} (mặc định)",
  "HABBLAUD_WORLD_URL recusada": "HABBLAUD_WORLD_URL bị từ chối",
  "Habblaud World: desligado ({0}).": "Habblaud World: tắt ({0}).",
  "A conta do Habblaud World foi excluída. O prédio e o perfil saíram do mundo na hora; o resto é apagado do banco em 7 dias e dos backups em até 30.": "Tài khoản Habblaud World đã bị xóa. Tòa nhà và hồ sơ đã rời thế giới ngay lập tức; phần còn lại sẽ bị xóa khỏi cơ sở dữ liệu trong vòng 7 ngày và khỏi bản sao lưu trong vòng 30 ngày.",
  "Habblaud World: conta excluída; a sessão e o world.json foram apagados deste computador.": "Habblaud World: đã xóa tài khoản; phiên và world.json đã bị gỡ khỏi máy này.",
  "os dados da conta só saem pela própria página do Habblaud": "dữ liệu tài khoản chỉ được lấy ra qua chính trang của Habblaud",
  "a conta, o personagem, os likes dados e recebidos, os bloqueios, as denúncias feitas e os dispositivos são apagados do banco.": "tài khoản, nhân vật, các lượt thích đã cho và đã nhận, các lượt chặn, các báo cáo bạn đã gửi và các thiết bị sẽ bị xóa khỏi cơ sở dữ liệu.",
  "Abre um e-mail para {0}: conte o que aconteceu, e uma pessoa revê o caso.": "Mở email tới {0}: hãy kể chuyện gì đã xảy ra, và một người thật sẽ xem xét trường hợp này.",
  "Abre um e-mail para {0}: se for engano, uma pessoa revê os números e tira o selo.": "Mở email tới {0}: nếu đó là nhầm lẫn, một người thật sẽ xem lại số liệu và gỡ huy hiệu.",
  "Avisar por e-mail antes de retirar meu prédio por inatividade": "Gửi email cho tôi trước khi tòa nhà bị gỡ vì không hoạt động",
  "Baixar meus dados": "Tải dữ liệu của tôi",
  "Conta e dados": "Tài khoản và dữ liệu",
  "Contestar por e-mail": "Khiếu nại qua email",
  "Dá para baixar os dados uma vez por dia. Tente de novo amanhã.": "Bạn chỉ tải dữ liệu được mỗi ngày một lần. Hãy thử lại vào ngày mai.",
  "Dúvidas ou pedidos sobre os seus dados: {0}.": "Câu hỏi hoặc yêu cầu về dữ liệu của bạn: {0}.",
  "Em 7 dias:": "Trong vòng 7 ngày:",
  "Em até 30 dias:": "Trong vòng 30 ngày:",
  "Em manutenção": "Đang bảo trì",
  "Excluindo…": "Đang xóa…",
  "Excluir a conta tira você do Habblaud World:": "Xóa tài khoản sẽ đưa bạn ra khỏi Habblaud World:",
  "Excluir a conta": "Xóa tài khoản",
  "Excluir conta": "Xóa tài khoản",
  "Excluir conta…": "Xóa tài khoản…",
  "Mandamos um código de 6 dígitos para {0}. Digite o código para excluir a conta.": "Chúng tôi đã gửi mã 6 chữ số tới {0}. Hãy nhập mã để xóa tài khoản.",
  "Mandar o código": "Gửi mã",
  "Na hora:": "Ngay lập tức:",
  "Não verificado": "Chưa xác minh",
  "O aviso de inatividade fica disponível depois de criar o personagem.": "Cảnh báo không hoạt động sẽ khả dụng sau khi bạn tạo nhân vật.",
  "O mundo marcou o seu prédio como \"não verificado\": os números pareceram fora do normal e estão em revisão. Ele continua no mundo, mas fora de placares e destaques.": "Thế giới đã đánh dấu tòa nhà của bạn là \"chưa xác minh\": số liệu của nó trông bất thường và đang được xem xét. Nó vẫn ở trong thế giới, nhưng không có trên bảng xếp hạng và mục nổi bật.",
  "o prédio e o perfil somem do mundo, e este computador sai da conta.": "tòa nhà và hồ sơ biến mất khỏi thế giới, và máy này đăng xuất khỏi tài khoản.",
  "Os números deste prédio pareceram fora do normal e estão em revisão; enquanto isso, ele fica fora de placares e destaques.": "Số liệu của tòa nhà này trông bất thường và đang được xem xét; trong thời gian đó, nó không có trên bảng xếp hạng và mục nổi bật.",
  "Para confirmar, mandamos um código de 6 dígitos para o e-mail da conta ({0}).": "Để xác nhận, chúng tôi gửi mã 6 chữ số tới email của tài khoản ({0}).",
  "Pronto: o arquivo {0} foi para a pasta de downloads.": "Xong: tệp {0} đã được lưu vào thư mục tải xuống của bạn.",
  "Recorrer por e-mail": "Khiếu nại qua email",
  "Se quiser guardar uma cópia, baixe os seus dados antes.": "Nếu muốn giữ một bản, hãy tải dữ liệu của bạn trước.",
  "Sem notícias deste Habblaud por 7 dias, o prédio some do mapa e, 30 dias depois, é retirado. O e-mail chega 3 dias antes da retirada.": "Nếu Habblaud này không có tin tức gì trong 7 ngày, tòa nhà sẽ biến mất khỏi bản đồ và, 30 ngày sau, bị gỡ bỏ. Email sẽ tới 3 ngày trước khi gỡ.",
  "Seus dados": "Dữ liệu của bạn",
  "somem também dos backups.": "chúng cũng biến mất khỏi các bản sao lưu.",
  "Tem certeza? O prédio e o perfil saem do mundo assim que você digitar o código.": "Bạn chắc chứ? Tòa nhà và hồ sơ sẽ rời thế giới ngay khi bạn nhập mã.",
  "Um arquivo JSON com o que o Habblaud World guarda da sua conta: e-mail, datas, personagem, visibilidade, dispositivos, prédio, likes dados, bloqueios e denúncias feitas. Dá para baixar uma vez por dia.": "Một tệp JSON chứa những gì Habblaud World lưu về tài khoản của bạn: email, ngày tháng, nhân vật, mức hiển thị, thiết bị, tòa nhà, lượt thích đã cho, lượt chặn và báo cáo bạn đã gửi. Bạn có thể tải mỗi ngày một lần.",
  "O pacote contradiz o anterior de um jeito que o Habblaud não produz: o mundo o descartou, e o prédio fica com o último aceito. As próximas remessas vão normalmente.": "Gói dữ liệu mâu thuẫn với gói trước theo cách Habblaud không tạo ra: thế giới đã bỏ nó, và tòa nhà giữ gói được chấp nhận gần nhất. Các lần tải lên tiếp theo vẫn đi bình thường.",

