  "Quem você bloqueia não te vê e você não vê a pessoa: na rua, nos prédios, nos cumprimentos e nos carimbos. Para bloquear alguém, abra o cartão da pessoa na cidade.": "Người bạn chặn sẽ không thấy bạn và bạn cũng không thấy họ: trên đường phố, trong tòa nhà, trong lời chào và con dấu. Để chặn ai đó, hãy mở thẻ của họ trong thành phố.",
